awk '
BEGIN {
    FS="[[:space:]]+";
    OFS="";
    step_count = 0;
}
# Find the header line to identify the start of thermo data
/Step/ && NF >= 4 {
    # This is the header line, skip it
    next;
}
# Look for lines that seem to contain the structured thermo data
/^[0-9]+[[:space:]]+[0-9.]+[[:space:]]+[-0-9.]+[[:space:]]+[-0-9.]+/[[:space:]]+/ {
    # The line structure is: Step Temp PotEng Press ...
    # We assume the 4th column (index 3) is Press
    if (NF >= 4) {
        step = $1;
        press = $4;

        # Check if the step is greater than 5000
        if (step > 5000) {
            # Accumulate values for later averaging
            press_sum += press;
            count++;
        }
    }
}
END {
    if (count > 0) {
        print "MEAN:" press_sum/count;
    } else {
        print "ERROR: No data found for steps > 5000.";
    }
}' run/log.lammps

