BEGIN {sum=0; count=0; in_data_block=0}
/^Step/ {
    if ($0 ~ /Step/ && $0 !~ /Loop time/) {
        in_data_block=1;
        next;
    }
    if ($0 ~ /Loop time/) {
        in_data_block=0;
    }
    next;
}
{
    # Check if we are in the data block, and if the first column is a number > 5000
    if (in_data_block && $1 ~ /^[0-9]+\.$/) {
        step = $1;
        if (step + 0 > 5000) {
            # Check if the 4th column exists and is numeric (safer than just relying on NF)
            if (NF >= 4 && $4 ~ /[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?/) {
                sum += $4 + 0;
                count++;
            }
        }
    }
}
END {
    if (count > 0) {
        printf "%.10f\n", sum/count;
    } else {
        print "ERROR: No steps > 5000 found in data.";
    }
}' run/log.lammps

